<?php require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/language.php';secure_session();verify_csrf();$u=require_login();$lang=array_key_exists($_POST['language']??'',supported_languages())?$_POST['language']:current_language();$theme=in_array($_POST['theme']??'', ['light','dark','system'],true)?$_POST['theme']:$u['theme'];db()->prepare('UPDATE users SET language=?,theme=? WHERE id=?')->execute([$lang,$theme,$u['id']]);setcookie('imgtr_lang',$lang,['expires'=>time()+31536000,'path'=>'/','secure'=>!empty($_SERVER['HTTPS']),'httponly'=>false,'samesite'=>'Lax']);json_response(['success'=>true]);
